import{_ as t,o as a,c as i,ai as r}from"./chunks/framework.DQi1ytmF.js";const u=JSON.parse('{"title":"Which primitive should I use?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concepts/choose-primitive.md","filePath":"guide/concepts/choose-primitive.md"}'),o={name:"guide/concepts/choose-primitive.md"};function s(n,e,h,c,d,l){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="which-primitive-should-i-use" tabindex="-1">Which primitive should I use? <a class="header-anchor" href="#which-primitive-should-i-use" aria-label="Permalink to &quot;Which primitive should I use?&quot;">​</a></h1><p>There are five primitives. They share the same shape — a name, a configuration, optional insertions — and differ only in <strong>where the value comes from</strong> and <strong>what triggers it</strong>.</p><h2 id="the-decision" tabindex="-1">The decision <a class="header-anchor" href="#the-decision" aria-label="Permalink to &quot;The decision&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where does the value live?</th><th>Use</th></tr></thead><tbody><tr><td>In memory, you own it</td><td><a href="/craft/guide/state/local-state.html"><code>state</code></a></td></tr><tr><td>On a server, read</td><td><a href="/craft/guide/state/server-state.html"><code>query</code></a></td></tr><tr><td>On a server, written</td><td><a href="/craft/guide/state/mutations.html"><code>mutation</code></a></td></tr><tr><td>In the URL&#39;s query string</td><td><a href="/craft/guide/state/url-state.html"><code>queryParams</code></a></td></tr><tr><td>Nowhere — it&#39;s an action with a lifecycle</td><td><a href="/craft/guide/state/async-process.html"><code>asyncProcess</code></a></td></tr></tbody></table><h2 id="the-same-table-by-symptom" tabindex="-1">The same table, by symptom <a class="header-anchor" href="#the-same-table-by-symptom" aria-label="Permalink to &quot;The same table, by symptom&quot;">​</a></h2><p><strong>&quot;I need a value the user can change.&quot;</strong> → <code>state</code>. It is the default. Reach for anything else only when the value&#39;s home is somewhere other than memory.</p><p><strong>&quot;I need to display data from an API.&quot;</strong> → <code>query</code>. It re-runs when its <code>params</code> change and carries <code>isLoading</code> / <code>status</code> / <code>exception</code> for you. Don&#39;t put a <code>query</code> result into a <code>state</code> — that&#39;s two sources of truth.</p><p><strong>&quot;I need to send something to an API.&quot;</strong> → <code>mutation</code>. Triggered explicitly with <code>.mutate(...)</code>. Connect it back to the read side with <a href="/craft/guide/state/react-on-mutation.html"><code>insertReactOnMutation</code></a> rather than reloading by hand.</p><p><strong>&quot;This filter should survive a refresh and be shareable.&quot;</strong> → <code>queryParams</code>. The URL becomes the source of truth; your query&#39;s <code>params</code> read from it.</p><p><strong>&quot;I need to run an async thing and know if it&#39;s running.&quot;</strong> → <code>asyncProcess</code>. Use it for operations that are not a server read or write: a file export, a share sheet, a delay, a Web API call.</p><h2 id="things-that-are-not-a-primitive" tabindex="-1">Things that are <em>not</em> a primitive <a class="header-anchor" href="#things-that-are-not-a-primitive" aria-label="Permalink to &quot;Things that are *not* a primitive&quot;">​</a></h2><ul><li><strong>Derived values</strong> — use Angular&#39;s <code>computed</code> inside an insertion. Craft doesn&#39;t replace signal derivation, it hosts it.</li><li><strong>Reusable logic across primitives</strong> — that&#39;s an <a href="/craft/guide/concepts/insertions.html">insertion</a>, not a primitive.</li><li><strong>A group of primitives with a name and a scope</strong> — that&#39;s a <a href="/craft/guide/app/craft-service.html"><code>craftService</code></a>.</li></ul><h2 id="what-they-have-in-common" tabindex="-1">What they have in common <a class="header-anchor" href="#what-they-have-in-common" aria-label="Permalink to &quot;What they have in common&quot;">​</a></h2><p>Whichever you pick, the mechanics are identical: the name comes first, the result is the primitive reference itself, <code>yield*</code> drives it inside any craft generator, and the last argument is an insertion.</p><p>That shared shape is one page: <strong><a href="/craft/guide/concepts/primitive-anatomy.html">Anatomy of a primitive</a></strong>. Read it once and every primitive page becomes just its own specifics. Advanced patterns that need to write a primitive from DI — wrappers, registries, WebMCP tools, seeding a query result — use the <a href="/craft/guide/concepts/primitive-anatomy.html#injectable-runtime-context">injectable runtime context</a>.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="/craft/guide/concepts/primitive-anatomy.html">Anatomy of a primitive</a></li><li><a href="/craft/learn/01-first-state.html">Learn: your first state</a></li><li><a href="/craft/guide/concepts/insertions.html">Insertions</a></li></ul>',17)])])}const p=t(o,[["render",s]]);export{u as __pageData,p as default};
